def test_cannot_reserve_more_than_available():
    inv = Inventory()
    inv.receive("A", 2)
    with pytest.raises(ValueError):
        inv.reserve("A", 3)


def test_release_returns_reserved_units_to_available():
    inv = Inventory()
    inv.receive("A", 10)
    inv.reserve("A", 6)

    inv.release("A", 2)

    assert inv.on_hand("A") == 10
    assert inv.reserved("A") == 4
    assert inv.available("A") == 6

    inv.release("A", 4)
    assert inv.reserved("A") == 0
    assert inv.available("A") == 10


